Create OR Replace View Acc_VGrant AS
SELECT
  GA.Id ,
  AA.Id   Acc_Id   , AA.Num    Acc_Num    , AA.Name   Acc_Name   ,
  AA.Num||' - '||AA.Name       Acc_FName  ,
