       M.Id  Mst_Id , M.Num  Mst_Num , M.Name  Mst_Name , M.BDate Mst_Date, M.Rem Mst_Rem   ,
       T.Id  Trn_Id , T.Ord  Trn_Ord , T.Bud   Trn_Bud  , T.Rem Trn_Rem,
